import{_ as o,a0 as n,w as d,s as r,I as a,x as i,a1 as t,A as l,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"每个 Linux 新手都应该知道的 10 个命令 | LCTT x X-CMD","titleTemplate":false,"description":"每个 Linux 新手都应该知道的 10 个命令 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每个 Linux 新手都应该知道的 10 个命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每个 Linux 新手都应该知道的 10 个命令 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180403 10 fundamental commands for new Linux users","title":"每个 Linux 新手都应该知道的 10 个命令","tag":"201805","desc":""},"relativePath":"201805/20180403 10 fundamental commands for new Linux users.md","filePath":"[post].md"}'),c={name:"201805/20180403 10 fundamental commands for new Linux users.md"};function h(u,e,m,g,k,b){const s=n("Link");return d(),r("div",null,[e[18]||(e[18]=a("h1",{id:"每个-linux-新手都应该知道的-10-个命令",tabindex:"-1"},[i("每个 Linux 新手都应该知道的 10 个命令 "),a("a",{class:"header-anchor",href:"#每个-linux-新手都应该知道的-10-个命令","aria-label":"Permalink to “每个 Linux 新手都应该知道的 10 个命令”"},"​")],-1)),e[19]||(e[19]=a("blockquote",null,[a("p",null,"通过这 10 个基础命令开始掌握 Linux 命令行。")],-1)),e[20]||(e[20]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/osdc_terminals.png?itok=CfBqYBah",alt:""})],-1)),a("p",null,[e[2]||(e[2]=i("你可能认为你是 Linux 新手，但实际上并不是。全球互联网用户有 ",-1)),t(s,{href:"https://hostingcanada.org/state-of-the-internet/"},{default:l(()=>[...e[0]||(e[0]=[i("3.74 亿",-1)])]),_:1}),e[3]||(e[3]=i("，他们都以某种方式使用 Linux，因为 Linux 服务器占据了互联网的 90%。大多数现代路由器运行 Linux 或 Unix，",-1)),t(s,{href:"https://www.top500.org/statistics/details/osfam/1"},{default:l(()=>[...e[1]||(e[1]=[i("TOP500 超级计算机",-1)])]),_:1}),e[4]||(e[4]=i(" 也依赖于 Linux。如果你拥有一台 Android 智能手机，那么你的操作系统就是由 Linux 内核构建的。",-1))]),e[21]||(e[21]=p(`<p>换句话说，Linux 无处不在。</p><p>但是使用基于 Linux 的技术和使用 Linux 本身是有区别的。如果你对 Linux 感兴趣，但是一直在使用 PC 或者 Mac 桌面，你可能想知道你需要知道什么才能使用 Linux 命令行接口（CLI），那么你来到了正确的地方。</p><p>下面是你需要知道的基本的 Linux 命令。每一个都很简单，也很容易记住。换句话说，你不必成为比尔盖茨就能理解它们。</p><h3 id="_1、-ls" tabindex="-1">1、 ls <a class="header-anchor" href="#_1、-ls" aria-label="Permalink to “1、 ls”">​</a></h3><p>你可能会想：“这是（is）什么东西？”不，那不是一个印刷错误 —— 我真的打算输入一个小写的 l。<code>ls</code>，或者说 “list”， 是你需要知道的使用 Linux CLI 的第一个命令。这个 list 命令在 Linux 终端中运行，以显示在存放在相应文件系统下的所有主要目录。例如，这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls /applications</span></span></code></pre></div><p>显示存储在 <code>applications</code> 文件夹下的每个文件夹，你将使用它来查看文件、文件夹和目录。</p><p>显示所有隐藏的文件都可以使用命令 <code>ls -a</code>。</p><h3 id="_2、-cd" tabindex="-1">2、 cd <a class="header-anchor" href="#_2、-cd" aria-label="Permalink to “2、 cd”">​</a></h3><p>这个命令是你用来跳转（或“更改”）到一个目录的。它指导你如何从一个文件夹导航到另一个文件夹。假设你位于 <code>Downloads</code> 文件夹中，但你想到名为 <code>Gym Playlist</code> 的文件夹中，简单地输入 <code>cd Gym Playlist</code> 将不起作用，因为 shell 不会识别它，并会报告你正在查找的文件夹不存在（LCTT 译注：这是因为目录名中有空格）。要跳转到那个文件夹，你需要包含一个反斜杠。改命令如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd Gym\\ Playlist</span></span></code></pre></div><p>要从当前文件夹返回到上一个文件夹，你可以在该文件夹输入 <code>cd ..</code>。把这两个点想象成一个后退按钮。</p><h3 id="_3、-mv" tabindex="-1">3、 mv <a class="header-anchor" href="#_3、-mv" aria-label="Permalink to “3、 mv”">​</a></h3><p>该命令将文件从一个文件夹转移到另一个文件夹；<code>mv</code> 代表“移动”。你可以使用这个简单的命令，就像你把一个文件拖到 PC 上的一个文件夹一样。</p><p>例如，如果我想创建一个名为 <code>testfile</code> 的文件来演示所有基本的 Linux 命令，并且我想将它移动到我的 <code>Documents</code> 文件夹中，我将输入这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mv /home/sam/testfile /home/sam/Documents/</span></span></code></pre></div><p>命令的第一部分（<code>mv</code>）说我想移动一个文件，第二部分（<code>home/sam/testfile</code>）表示我想移动的文件，第三部分（<code>/home/sam/Documents/</code>）表示我希望传输文件的位置。</p><h3 id="_4、-快捷键" tabindex="-1">4、 快捷键 <a class="header-anchor" href="#_4、-快捷键" aria-label="Permalink to “4、 快捷键”">​</a></h3><p>好吧，这不止一个命令，但我忍不住把它们都包括进来。为什么？因为它们能节省时间并避免经历头痛。</p><ul><li><code>CTRL+K</code> 从光标处剪切文本直至本行结束</li><li><code>CTRL+Y</code> 粘贴文本</li><li><code>CTRL+E</code> 将光标移到本行的末尾</li><li><code>CTRL+A</code> 将光标移动到本行的开头</li><li><code>ALT+F</code> 跳转到下一个空格处</li><li><code>ALT+B</code> 回到前一个空格处</li><li><code>ALT+Backspace</code> 删除前一个词</li><li><code>CTRL+W</code> 剪切光标前一个词</li><li><code>Shift+Insert</code> 将文本粘贴到终端中</li><li><code>Ctrl+D</code> 注销</li></ul><p>这些命令在许多方面都能派上用场。例如，假设你在命令行文本中拼错了一个单词：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get intall programname</span></span></code></pre></div><p>你可能注意到 <code>install</code> 拼写错了，因此该命令无法工作。但是快捷键可以让你很容易回去修复它。如果我的光标在这一行的末尾，我可以按下两次 <code>ALT+B</code> 来将光标移动到下面用 <code>^</code> 符号标记的地方：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get^intall programname</span></span></code></pre></div><p>现在，我们可以快速地添加字母 <code>s</code> 来修复 <code>install</code>，十分简单！</p><h3 id="_5、-mkdir" tabindex="-1">5、 mkdir <a class="header-anchor" href="#_5、-mkdir" aria-label="Permalink to “5、 mkdir”">​</a></h3><p>这是你用来在 Linux 环境下创建目录或文件夹的命令。例如，如果你像我一样喜欢 DIY，你可以输入 <code>mkdir DIY</code> 为你的 DIY 项目创建一个目录。</p><h3 id="_6、-at" tabindex="-1">6、 at <a class="header-anchor" href="#_6、-at" aria-label="Permalink to “6、 at”">​</a></h3><p>如果你想在特定时间运行 Linux 命令，你可以将 <code>at</code> 添加到语句中。语法是 <code>at</code> 后面跟着你希望命令运行的日期和时间，然后命令提示符变为 <code>at&gt;</code>，这样你就可以输入在上面指定的时间运行的命令。</p><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>at 4:08 PM Sat</span></span>
<span class="line"><span>at&gt; cowsay &#39;hello&#39;</span></span>
<span class="line"><span>at&gt; CTRL+D</span></span></code></pre></div><p>这将会在周六下午 4:08 运行 <code>cowsay</code> 程序。</p><h3 id="_7、-rmdir" tabindex="-1">7、 rmdir <a class="header-anchor" href="#_7、-rmdir" aria-label="Permalink to “7、 rmdir”">​</a></h3><p>这个命令允许你通过 Linux CLI 删除一个目录。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rmdir testdirectory</span></span></code></pre></div><p>请记住，这个命令不会删除里面有文件的目录。这只在删除空目录时才起作用。</p><h3 id="_8、-rm" tabindex="-1">8、 rm <a class="header-anchor" href="#_8、-rm" aria-label="Permalink to “8、 rm”">​</a></h3><p>如果你想删除文件，<code>rm</code> 命令就是你想要的。它可以删除文件和目录。要删除一个文件，键入 <code>rm testfile</code>，或者删除一个目录和里面的文件，键入 <code>rm -r</code>。</p><h3 id="_9、-touch" tabindex="-1">9、 touch <a class="header-anchor" href="#_9、-touch" aria-label="Permalink to “9、 touch”">​</a></h3><p><code>touch</code> 命令，也就是所谓的 “make file 的命令”，允许你使用 Linux CLI 创建新的、空的文件。很像 <code>mkdir</code> 创建目录，<code>touch</code> 会创建文件。例如，<code>touch testfile</code> 将会创建一个名为 testfile 的空文件。</p><h3 id="_10、-locate" tabindex="-1">10、 locate <a class="header-anchor" href="#_10、-locate" aria-label="Permalink to “10、 locate”">​</a></h3><p>这个命令是你在 Linux 系统中用来查找文件的命令。就像在 Windows 中搜索一样，如果你忘了存储文件的位置或它的名字，这是非常有用的。</p><p>例如，如果你有一个关于区块链用例的文档，但是你忘了标题，你可以输入 <code>locate -blockchain</code> 或者通过用星号分隔单词来查找 &quot;blockchain use cases&quot;，或者星号（<code>*</code>）。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>locate -i*blockchain*use*cases*</span></span></code></pre></div><p>还有很多其他有用的 Linux CLI 命令，比如 <code>pkill</code> 命令，如果你开始关机但是你意识到你并不想这么做，那么这条命令很棒。但是这里描述的 10 个简单而有用的命令是你开始使用 Linux 命令行所需的基本知识。</p><hr>`,46)),a("p",null,[e[6]||(e[6]=i("via: ",-1)),t(s,{href:"https://opensource.com/article/18/4/10-commands-new-linux-users"},{default:l(()=>[...e[5]||(e[5]=[i("https://opensource.com/article/18/4/10-commands-new-linux-users",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=i("作者：",-1)),t(s,{href:"https://opensource.com/users/sambocetta"},{default:l(()=>[...e[7]||(e[7]=[i("Sam Bocetta",-1)])]),_:1}),e[11]||(e[11]=i(" 译者：",-1)),t(s,{href:"https://github.com/MjSeven"},{default:l(()=>[...e[8]||(e[8]=[i("MjSeven",-1)])]),_:1}),e[12]||(e[12]=i(" 校对：",-1)),t(s,{href:"https://github.com/wxy"},{default:l(()=>[...e[9]||(e[9]=[i("wxy",-1)])]),_:1})]),a("p",null,[e[15]||(e[15]=i("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[13]||(e[13]=[i("LCTT",-1)])]),_:1}),e[16]||(e[16]=i(" 原创编译，",-1)),t(s,{href:"https://linux.cn/"},{default:l(()=>[...e[14]||(e[14]=[i("Linux中国",-1)])]),_:1}),e[17]||(e[17]=i(" 荣誉推出",-1))])])}const C=o(c,[["render",h]]);export{L as __pageData,C as default};
